effect.shader:
vec4 sampleLayer(vec2 uv){ return texture2DCv(inputImg.texture, uv); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = sampleLayer(uv);
float pulse = 0.5 + 0.5 * sin(acTime * pulseSpeed * 6.2831853);
float g = amount * pulse;
vec3 gold = warmColor.rgb;
vec3 graded = mix(src.rgb, src.rgb * gold * 1.6, goldTint);
vec3 outRgb = mix(graded, graded + gold * 0.35, g);
if (vignetteOn) {
    vec2 d = uv - vec2(0.5);
    float vig = 1.0 - smoothstep(0.25, 0.85, length(d) * 1.4);
    outRgb *= mix(0.65, 1.0, vig);
}
gl_FragColor = vec4(clamp(outRgb, 0.0, 1.0), src.a);
}
